typedef unsigned long big_int;

class stringx;
class string_buf {
  friend class stringx;
  friend stringx operator+(const stringx&, const stringx&);
  big_int *data;
  int ref_count;
  int char_length;
  int block_length;
  int max_blocks;
public:
  inline int compare(const char *str) const {
    int i;
    const char *a = reinterpret_cast<const char *>(data);
    for (i = 0; i < char_length; i++) {
      if (str[i] == '\0') return -1;
      if (a[i] == str[i]) continue;
      if (str[i] > a[i]) return 1;
      if (str[i] < a[i]) return -1;
    }
    if (str[i] == '\0') return 0;
    return 1;
  }
};

class stringx {
  friend stringx operator+(const stringx&, const stringx&);
protected:
  char *chars;
  string_buf *my_buf;
public:
  stringx();
  stringx(const stringx&);
  ~stringx();
  void append(const stringx&);
  void make_room(int);
  inline const char *c_str() const { return chars; }
  inline int length() const { return my_buf->char_length; }
  friend inline bool operator!=(const stringx& lhs, const char *rhs) { return lhs.my_buf->compare(rhs) != 0; }
};

inline stringx operator+(const stringx& lhs, const stringx& rhs) {
  stringx foo;
  foo.make_room(lhs.my_buf->char_length + rhs.my_buf->char_length);
  foo.append(lhs);
  foo.append(rhs);
  return foo;
}

class filespec {
public:
  stringx path;
  stringx name;
  stringx ext;
  explicit filespec(const stringx&);
};

class os_file {
public:
  enum mode_flags { FILE_READ=1, FILE_WRITE=2, FILE_MODIFY=3, FILE_APPEND=4 };
  void open(const stringx&, int);
  bool operator!() const { return false; }
private:
  stringx name;
  int flags;
  bool opened;
  bool eof;
  bool from_cd;
  char implementation[32];
};

class multistash { char padding[708]; public: bool stash_file_is_open; char rest[83]; };
class stash {
public:
  static int curstash;
  static multistash substash[5];
  static bool is_stash_open() { return substash[curstash].stash_file_is_open; }
  static int get_current_stash() { return curstash; }
  static void set_current_stash(int cs) { curstash=cs; }
  static bool file_exists(const char*);
  bool open(const char*);
  bool is_open() const { return opened; }
private:
  void *index;
  bool opened;
  bool eof;
  unsigned fp;
  unsigned max_fp;
  char fullname[32];
};

class text_file {
public:
  void open(const stringx&, int);
private:
  void refill_buf();
  os_file io;
  stash the_stash;
  int my_stash;
  char *buf;
  int bufpos;
  int bufamt;
  bool use_stash;
  int pushbackdata;
};

